Given a binary tree and a sum, return true if the tree has a root-to-leaf path such that adding up all the values along the path equals the given sum. Return false if no such path can be found.  Example:Input:Output: True Explanation:  Root to leaf path sum, existing in this tree are:10 -> 8 -> 3  =  2110 -> 8 -> 5  = 2310 -> 2 -> 2 = 14So it is possible to get sum = 21Try It YourselfTable of Content[Expected Approach - 1] Using Recursion - O(n) Time and O(h) Space[Expected Approach - 2] Using Iterative - O(n) Time and O(h) Space[Expected Approach - 1] Using Recursion - O(n) Time and O(h) SpaceThe idea is to recursively move to left and right subtree and decrease sum by the value of the current node and if at any point the current node is equal to a leaf node and remaining sum is equal to zero then the answer is true.Follow the given steps to solve the problem using the above approach:Recursively move to the left and right subtree and at each call decrease the sum by the value of the current node.If at any level the current node is a leaf node and the remaining sum is equal to zero then return true.Below is the implementation of the above approach:
            C++

    // C++ Program to Check if Root to leaf path
// sum equal to a given number

#include <bits/stdc++.h>

using namespace std;

class Node {
public:
    Node *left, *right;
    int data;

    Node(int key) {
        data = key;
        left = nullptr;
        right = nullptr;
    }
};

// Given a tree and a sum, return true if there is a path from
// the root down to a leaf, such that adding up all the values
// along the path equals the given sum.
bool hasPathSum(Node* root, int sum) {
    if (root == NULL)
        return 0;

    int subSum = sum - root->data;

    // If we reach a leaf node and sum becomes 0 then return true
    if (subSum == 0 && root->left == nullptr && root->right == nullptr)
        return 1;

    // Otherwise check both subtrees
    bool left = 0, right = 0;

    if (root->left)
        left = hasPathSum(root->left, subSum);
    if (root->right)
        right = hasPathSum(root->right, subSum);

    return left || right;
}

int main() {

    int sum = 21;

    // Constructed binary tree is
    //         10
    //       /    \
    //      8      2
    //     / \    /
    //    3   5  2

    Node* root = new Node(10);
    root->left = new Node(8);
    root->right = new Node(2);
    root->left->left = new Node(3);
    root->left->right = new Node(5);
    root->right->left = new Node(2);

    if(hasPathSum(root, sum)) {
      cout << "True"<< endl;
    }
  	else cout << "False";

    return 0;
}


